using Pf2e.Client.State;

namespace Pf2e.Client.Catalog;

/// <summary>Our own words, never Paizo's: the ingest withholds rule prose, and these fill the gap
/// with a plain explanation a new player can act on.</summary>
public sealed record CategoryNote(string Section, string Blurb);

public static class GroupNotes
{
    public static IReadOnlyDictionary<GroupKey, string> All { get; } = new Dictionary<GroupKey, string>
    {
        [GroupKey.Build] = "The choices that make a character: who they are, where they come from, and what they trained as.",
        [GroupKey.Feats] = "The special abilities you pick as you level up, including archetypes that borrow from outside your class.",
        [GroupKey.Spells] = "Every spell and ritual, and the four traditions of magic that decide which ones a caster can learn.",
        [GroupKey.Gear] = "Everything you can carry, wear or wield, from rope and rations to magic weapons, relics and the curses they hide.",
        [GroupKey.Play] = "What you actually do at the table: the actions you take, the conditions that hit you, and the skills you roll.",
        [GroupKey.Reference] = "The lookup shelf: traits, languages, gods, companions and the other terms the rest of the rules point to.",
    };

    public static string Of(GroupKey group) => All.GetValueOrDefault(group, string.Empty);
}

