{
    public static IReadOnlyDictionary<string, string> All { get; } =
        new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["Manipulate"] = "You have to move your hands to do this, so it can trigger reactions like Reactive Strike.",
            ["Concentrate"] = "Takes mental focus. You can't do it while too distracted, and some reactions punish it.",
            ["Move"] = "You change position doing this, so it can trigger reactions from enemies you move near or past.",
            ["Attack"] = "Counts toward your multiple attack penalty: each attack after the first in a turn is harder to land.",
            ["Flourish"] = "A showy move. You can use only one action with this trait per turn.",
            ["Press"] = "A follow-up move. You can only use it if you've already attacked this turn, so it always takes a penalty.",
            ["Open"] = "An opener. You can only use it if you haven't used an attack action yet this turn.",
            ["Stance"] = "A fighting posture you enter. It lasts until you leave it or fight ends, and you can hold only one at a time.",
            ["Fortune"] = "Lets you roll twice and keep the better. Only one fortune effect applies to a roll.",
            ["Misfortune"] = "Makes you roll twice and keep the worse. If fortune and misfortune both apply, they cancel out.",
            ["Incapacitation"] = "Knocks a target out of the fight, so creatures of much higher level than the effect get a better outcome.",
